/* MEAP · Forms, letters & reports: template engine, management letter, opinion helper */
'use strict';
/* ================= a9 · Forms, letters & reports: template engine, auto-generated management letter, opinion helper ================= */
const TPLM={};TPL.forEach(t=>{TPLM[t.id]=t});
/* standards string → tokens: "ISRE 2400", "ISQM 2", "IIA", "700"… ; only ISA numbers present in the ISA index are linked */
const ISASET=new Set(ISA.map(s=>String(s[0])));
function stdTokens(s){return (String(s||'').match(/(ISRE|ISRS|ISAE|ISSA|ISQM|IAS|IFRS)\s*\d+|\(?IIA\)?|\d{3}/g)||[]).map(x=>x.replace(/[()]/g,''))}
const stdChip=x=>ISASET.has(x)?`<a class="b isa" href="${L('isa/'+x)}">ISA ${esc(x)}</a>`:`<span class="b isa">${esc(x)}</span>`;
const DOCST=[['NS','لم يبدأ'],['DR','مسودة'],['RV','قيد المراجعة'],['FN','نهائي']];
const MONTHS=['يناير','فبراير','مارس','أبريل','مايو','يونيو','يوليو','أغسطس','سبتمبر','أكتوبر','نوفمبر','ديسمبر'];
const fmtLongDate=s=>{const m=/^(\d{4})-(\d{2})-(\d{2})/.exec(String(s||''));return m?`${+m[3]} ${MONTHS[+m[2]-1]} ${m[1]}`:String(s||'')};
const JUR={INT:['المعايير الدولية للمراجعة','قواعد السلوك الدولية للمحاسبين المهنيين (بما في ذلك المعايير الدولية للاستقلال) الصادرة عن مجلس المعايير الدولية لأخلاقيات المحاسبين (IESBA)'],
 EG:['معايير المراجعة المصرية','قواعد السلوك المهني ذات الصلة المطبقة في جمهورية مصر العربية (بحاجة لمراجعة مهني لتسمية المرجع النافذ)'],
 SA:['المعايير الدولية للمراجعة المعتمدة في المملكة العربية السعودية','قواعد السلوك والأخلاقيات المهنية المعتمدة في المملكة العربية السعودية']};
/* engagement-level data shared by all templates (stored as eng.* keys) */
const ENGF=[['partner','الشريك المسؤول عن الارتباط'],['city','المدينة'],['rdate','تاريخ التقرير / الخطابات','date'],['addr','المخاطَب في التقرير','','السادة مساهمي الشركة'],['tcwg','المكلفون بالحوكمة','','مجلس الإدارة'],['ceo','الرئيس التنفيذي / المدير العام'],['cfo','المدير المالي'],['cur','العملة','','جنيه مصري'],['fees','الأتعاب'],['law','القانون / النظام المنظِّم','','قانون الشركات المعمول به'],['regulator','الجهة الرقابية'],['deadline','الموعد النهائي للتقرير','date'],['jur','الاختصاص الافتراضي','jur','INT']];
function docOpt(id,o,st){st=st||CUR.eng;const tp=TPLM[id];const def=(tp&&tp.opts||[]).find(x=>x[0]===o);const v=st?st.get('doc.'+id+'.o.'+o,null):null;if(v!=null)return v;if(o==='jur')return st?st.get('eng.jur','INT'):'INT';return def?def[3]:''}
function docVars(id,st){st=st||CUR.eng;const tp=TPLM[id]||{};const g=(k,d)=>st?st.get(k,d):d;const jur=JUR[docOpt(id,'jur',st)]||JUR.INT;
 const v={company:CUR.company&&st===CUR.eng?CUR.company.name:(st&&st.meta&&st.meta.companyName)||'',year:g('eng.year',''),period:fmtLongDate(g('eng.period','')),fw:g('eng.fw',''),firm:(SETTINGS&&SETTINGS.firmName)||'',
  om:g('eng.mat',''),pm:g('eng.pm',''),ct:g('eng.ct',''),today:fmtLongDate(today()),stdname:jur[0],ethics:jur[1]};
 ENGF.forEach(f=>{if(f[2]==='jur')return;const x=g('eng.'+f[0],'');v[f[0]]=f[2]==='date'?fmtLongDate(x||(f[0]==='rdate'?today():'')):(x||f[3]||'')});
 (tp.vars||[]).forEach(x=>{v[x[0]]=x[2]||''});
 for(const [k,val] of st?st.entries('doc.'+id+'.v.'):[]){v[k.slice(('doc.'+id+'.v.').length)]=val}return v}
const VARLABEL={};TPLVARS.forEach(x=>{VARLABEL[x[0]]=x[1]});
/* condition grammar: OR ';' · AND '&' · atom: x | !x | x=V|W | x!=V|W */
function evalCond(expr,get){if(!expr)return true;return String(expr).split(';').some(cl=>cl.split('&').every(at=>{at=at.trim();if(!at)return true;let m;
 if((m=/^([\w]+)(!?=)(.*)$/.exec(at))){const val=String(get(m[1])??'');const vals=m[3].split('|');return m[2]==='='?vals.includes(val):!vals.includes(val)}
 if(at[0]==='!'){const x=get(at.slice(1));return !x||x==='0'}const x=get(at);return !!x&&x!=='0'}))}
/* inline conditional segments: {cond}text{cond2}text{/}rest ; consecutive markers are AND-ed */
function condText(s,get){const re=/(^|[^{])\{([^{}]*)\}(?!\})/g;let out='',cur=null,last=0,m,prevEnd=-1;
 while((m=re.exec(s))){const st=m.index+m[1].length;const seg=s.slice(last,st);if(cur===null||evalCond(cur,get))out+=seg;const c=m[2].trim();
  if(c==='/')cur=null;else cur=(prevEnd===st&&cur&&cur!=='/')?cur+'&'+c:c;last=re.lastIndex;prevEnd=re.lastIndex}
 const tail=s.slice(last);if(cur===null||evalCond(cur,get))out+=tail;return out}
function fillVars(s,vars,html){return s.replace(/\{\{(\w+)\}\}/g,(_,k)=>{const v=vars[k];if(v!=null&&String(v).trim()!=='')return html?esc(v):String(v);const lab=VARLABEL[k]||k;return html?`<mark class="miss" title="حقل غير مكتمل">[${esc(lab)}]</mark>`:`[${lab}]`})}
function secCond(sec){const h=sec[1]||'';const m=/^\{([^{}]*)\}(.*)$/.exec(h);return{cond:[sec[3],m?m[1]:''].filter(Boolean).join('&'),head:m?m[2]:h}}
/* plain text of a section (conditions resolved, vars filled) — used as default for edits and for exports */
function secPlain(id,sec,get,vars){return sec[2].map(p=>condText(p,get)).filter(p=>p.trim()).map(p=>fillVars(p,vars,false)).join('\n\n')}
function parasHTML(text,vars,id){const lines=String(text).split(/\n{2,}|\n(?=- )/);let html='',ul=false;
 for(let p of lines){p=p.trim();if(!p)continue;const auto=/^\[\[([A-Z_]+)\]\]$/.exec(p);if(auto){if(ul){html+='</ul>';ul=false}html+=`<div class="auto" data-auto="${auto[1]}">${AUTO[auto[1]]?AUTO[auto[1]](id):''}</div>`;continue}
  if(p.startsWith('- ')){if(!ul){html+='<ul>';ul=true}html+=`<li>${fillVars(p.slice(2),vars,true)}</li>`}else{if(ul){html+='</ul>';ul=false}html+=`<p>${fillVars(p,vars,true).replace(/\n/g,'<br>')}</p>`}}
 if(ul)html+='</ul>';return html}
function docModel(id,st){st=st||CUR.eng;const tp=TPLM[id];const get=o=>docOpt(id,o,st);const vars=docVars(id,st);const out=[];
 for(const sec of tp.secs){const {cond,head}=secCond(sec);if(!evalCond(cond,get))continue;const ov=st.get('doc.'+id+'.s.'+sec[0],null);const plain=secPlain(id,sec,get,vars);
  out.push({sid:sec[0],head:condText(head,get),plain,text:ov!=null?ov:plain,edited:ov!=null,auto:/\[\[[A-Z_]+\]\]/.test(plain)})}return{tp,vars,secs:out}}
function docHTML(id,edit){const m=docModel(id);const ed=edit&&can('edit');
 return `<article class="doc" id="docbody" lang="ar"><div class="print-head">${esc(SETTINGS.firmName||'')} · ${esc(m.tp.ar)} · ${esc(m.vars.company)} · ${esc(m.vars.year)}</div>${m.secs.map(s=>`<section class="docsec${s.edited?' edited':''}" data-sec="${esc(s.sid)}">${s.head?`<h3>${esc(s.head)}</h3>`:''}
  ${ed&&!s.auto?`<div class="row noprint secbar"><button class="btn g sm" type="button" data-act="docsec" data-id="${esc(id)}" data-sec="${esc(s.sid)}" aria-expanded="false">✎ تحرير القسم</button>${s.edited?`<span class="b M">معدَّل يدويًا</span><button class="btn g sm" type="button" data-act="docsecreset" data-id="${esc(id)}" data-sec="${esc(s.sid)}">↺ استعادة النص الآلي</button>`:''}</div>`:''}
  <div class="secbody">${parasHTML(s.text,m.vars,id)}</div></section>`).join('')}</article>`}
function docSnapshot(store,id){const tp=TPLM[id];if(!tp)return null;const o={format:'MEAP-document',version:1,template:id,title:{ar:tp.ar,en:tp.en},standards:tp.isa,workingPapers:split(tp.wp),status:store.get('doc.'+id+'.st','NS'),options:{},variables:{},sectionOverrides:{},updatedAt:localISO()};
 for(const [k,v] of store.entries('doc.'+id+'.')){const r=k.slice(('doc.'+id+'.').length);if(r.startsWith('o.'))o.options[r.slice(2)]=v;else if(r.startsWith('v.'))o.variables[r.slice(2)]=v;else if(r.startsWith('s.'))o.sectionOverrides[r.slice(2)]=v}
 if(store===CUR.eng){try{o.rendered=docModel(id).secs.map(s=>({section:s.sid,heading:s.head,text:s.auto?docAutoPlain(s.text,id):s.text}))}catch(e){logErr('docSnapshot render '+id,e)}}return o}
function docAutoPlain(text,id){const d=document.createElement('div');d.innerHTML=parasHTML(text,docVars(id),id);return d.innerText}

/* ---------- Management letter: points generated from findings, exceptions, ICQ answers, TB differences ---------- */
const MLCAT={SD:['قصور جوهري في الرقابة الداخلية (Significant Deficiency)',1],CD:['قصور في الرقابة الداخلية (Control Deficiency)',2],NC:['عدم التزام بالقوانين أو السياسات (Non-compliance)',3],OT:['أمور أخرى وملاحظات تحسين (Other Matters)',4]};
const MLF=[['cond','الملاحظة (Condition)'],['crit','المعيار (Criteria)'],['cause','السبب (Cause)'],['eff','الأثر / المخاطر (Effect)'],['rec','التوصية (Recommendation)'],['mr','رد الإدارة (Management Response)'],['owner','المسؤول عن التنفيذ'],['due','التاريخ المستهدف']];
const ftypeCat=tp=>/Significant/i.test(tp)?'SD':/Control/i.test(tp)?'CD':/Compliance/i.test(tp)?'NC':'OT';
const MLDEF={crit:{SD:'تتطلب الرقابة الداخلية الفعالة أن تُصمَّم الضوابط وتُنفَّذ وتعمل بما يمنع أو يكتشف ويصحح التحريفات الجوهرية في الوقت المناسب.',CD:'تقتضي الممارسات السليمة للرقابة الداخلية توثيق الضوابط واعتمادها وتنفيذها باتساق.',NC:'يتطلب الالتزام بالقوانين واللوائح والسياسات الداخلية المعمول بها.',OT:'أفضل الممارسات المهنية وسياسات المنشأة.'},
 eff:{SD:'قد يؤدي ذلك إلى تحريف جوهري في القوائم المالية لا يُمنع أو يُكتشف في الوقت المناسب.',CD:'يزيد ذلك من خطر حدوث أخطاء أو مخالفات وعدم اكتشافها في الوقت المناسب.',NC:'قد يعرّض المنشأة لغرامات أو جزاءات أو مخاطر سمعة.',OT:'فرصة لتحسين الكفاءة والرقابة.'},
 rec:{SD:'نوصي باتخاذ إجراء تصحيحي عاجل بتصميم الضابط وتطبيقه ومتابعة فعاليته، وإبلاغ المكلفين بالحوكمة بالتقدم.',CD:'نوصي بتعزيز الضابط وتوثيقه واعتماده ومتابعة الالتزام به دوريًا.',NC:'نوصي بمعالجة حالة عدم الالتزام وتعزيز آليات رصد الالتزام.',OT:'نوصي بدراسة الملاحظة واتخاذ ما يلزم.'}};
function mlPoints(st){st=st||CUR.eng;const P=[];const add=p=>{const o=k=>st.get('ml.'+p.key+'.'+k,null);MLF.forEach(f=>{const x=o(f[0]);if(x!=null)p[f[0]]=x});['cat','sev','title'].forEach(k=>{const x=o(k);if(x!=null)p[k]=x});
  ['crit','eff','rec'].forEach(k=>{if(!p[k])p[k]=MLDEF[k][p.cat]||''});const inc=o('inc');p.inc=inc==null?p.defInc!==false:!!inc;p.ord=num(o('ord'))||0;P.push(p)};
 const F_=recs(st,'f');const fProc=new Set(F_.map(f=>f.proc).filter(Boolean));
 F_.forEach(f=>{if(f.status==='Cleared')return;const cat=ftypeCat(f.type||'');add({key:'f-'+f.id,src:'f:'+f.id,cat,sev:f.sev||'M',title:(f.title||String(f.desc||'').split(/[.\n،]/)[0]).slice(0,90),cond:f.desc||'',crit:f.crit||'',cause:f.cause||'',eff:f.eff||'',rec:f.rec||'',mr:f.mr||'',owner:f.owner||'',due:f.due||'',amt:f.amt||'',ref:f.ref||'',acc:f.acc||'',defInc:!/Misstatement/i.test(f.type||'')})});
 for(const p of PROCS){if(st.get('st.'+p.id,'NS')!=='EX'||fProc.has(p.id))continue;const ctl=['TOC','ITGC'].includes(p.t);add({key:'ex-'+p.id,src:'pp:'+p.id,cat:ctl?'CD':'OT',sev:p.lv||'M',title:(ctl?'استثناء في اختبار رقابة: ':'استثناء في إجراء: ')+p.tx.replace(/^\[[^\]]*\]\s*/,'').slice(0,80),cond:'نتج عن تنفيذ الإجراء «'+p.tx+'» استثناء.'+(st.get('nt.'+p.id,'')?' '+st.get('nt.'+p.id,''):''),ref:split(p.wp)[0]||'',defInc:true})}
 for(const [k,v] of st.entries('wp.')){const m=/^wp\.([^.]+)\.ck\.([^.]+)$/.exec(k);if(!m||v!=='N')continue;const w=WP[m[1]];if(!w||w.k!=='icq')continue;const item=(w.it||[]).find(x=>fnv(x)===m[2]);if(!item)continue;
  add({key:'ck-'+m[1]+'-'+m[2],src:'wp:'+m[1],cat:'CD',sev:'M',title:'إجابة «لا» في استبيان الرقابة '+m[1],cond:'السؤال: «'+item+'» — الإجابة: لا.'+(st.get('wp.'+m[1]+'.ckc.'+m[2],'')?' التعليق: '+st.get('wp.'+m[1]+'.ckc.'+m[2],''):''),ref:m[1],defInc:true})}
 if(typeof TBSTORE!=='undefined')TBSTORE.leadDiffs().forEach(d=>add({key:'tb-'+d.ref,src:'wp:'+d.ref,ref:d.ref,cat:'OT',sev:Math.abs(d.diff)>num(st.get('eng.pm',0))?'H':'M',title:'فرق غير مطابق بين ميزان المراجعة وورقة العمل '+d.name,cond:`يوجد فرق قدره ${fmtN(d.diff)} بين رصيد ميزان المراجعة (${fmtN(d.tb)}) وإجمالي ورقة العمل (${fmtN(d.wp)}) في ${d.name}.`,defInc:false}));
 return P.sort((a,b)=>(a.ord-b.ord)||(MLCAT[a.cat][1]-MLCAT[b.cat][1])||('HML'.indexOf(a.sev)-'HML'.indexOf(b.sev))||(num(b.amt)-num(a.amt)))}
function mlSeen(){return new Set(G('ml.$seen',[])||[])}
const sevL=s=>({H:'مرتفعة',M:'متوسطة',L:'منخفضة'}[s]||s);
function mlPointHTML(p,i,resp){return `<section class="mlp"><h4>${i}. ${esc(p.title||'')} <span class="b ${p.sev}">${esc(sevL(p.sev))}</span></h4>${MLF.filter(f=>(resp||f[0]!=='mr')&&(f[0]!=='owner'&&f[0]!=='due'||p[f[0]])).map(f=>p[f[0]]?`<p><b>${esc(f[1])}:</b> ${esc(p[f[0]])}</p>`:'').join('')}${p.ref?`<p class="mut small">المرجع: ${esc(p.ref)}${p.amt?' · المبلغ: '+esc(p.amt):''}</p>`:''}</section>`}
const AUTO={
 ML_SUMMARY:()=>{const P=mlPoints().filter(p=>p.inc);if(!P.length)return '<p>لم تُحدد ملاحظات للإبلاغ عنها.</p>';const rows=Object.keys(MLCAT).map(c=>[c,['H','M','L'].map(s=>P.filter(p=>p.cat===c&&p.sev===s).length)]).filter(r=>r[1].some(Boolean));
  return `<table class="dtab"><thead><tr><th>الفئة</th><th>مرتفعة</th><th>متوسطة</th><th>منخفضة</th><th>الإجمالي</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${esc(MLCAT[r[0]][0])}</td>${r[1].map(n=>`<td>${n}</td>`).join('')}<td><b>${r[1].reduce((a,b)=>a+b,0)}</b></td></tr>`).join('')}</tbody></table>`},
 ML_POINTS:id=>{const resp=docOpt(id||'mgmtletter','resp')!=='0';const P=mlPoints().filter(p=>p.inc);if(!P.length)return '<p>لا توجد ملاحظات.</p>';let n=0;return Object.keys(MLCAT).map(c=>{const L_=P.filter(p=>p.cat===c);return L_.length?`<h4 class="mlc">${esc(MLCAT[c][0])}</h4>`+L_.map(p=>mlPointHTML(p,++n,resp)).join(''):''}).join('')},
 ML_SIG:()=>{const P=mlPoints().filter(p=>p.inc&&p.cat==='SD');return P.length?P.map((p,i)=>mlPointHTML(p,i+1,true)).join(''):'<p>لم نحدد أوجه قصور مهمة في الرقابة الداخلية.</p>'},
 ML_CTRL:()=>{const P=mlPoints().filter(p=>p.inc&&(p.cat==='SD'||p.cat==='CD'));return P.length?P.map((p,i)=>mlPointHTML(p,i+1,true)).join(''):'<p>لم نحدد أوجه قصور في الرقابة الداخلية.</p>'},
 ML_PRIOR:()=>{const L_=[];for(const [k,v] of CUR.eng.entries('mlp.')){if(/^mlp\.[^.]+$/.test(k)&&v)L_.push(Object.assign({id:k.slice(4)},v))}
  return (L_.length?`<table class="dtab"><thead><tr><th>#</th><th>الملاحظة في السنة السابقة</th><th>التوصية</th><th>الوضع الحالي</th></tr></thead><tbody>${L_.map((x,i)=>`<tr><td>${i+1}</td><td>${esc(x.cond||'')}</td><td>${esc(x.rec||'')}</td><td>${can('edit')?`<select class="sel noprint-sel" data-k="mlp.${esc(x.id)}.st" data-dv="NI" aria-label="وضع التنفيذ">${[['NI','لم يُنفذ'],['PI','نُفذ جزئيًا'],['IM','نُفذ'],['NA','لم يعد ينطبق']].map(o=>`<option value="${o[0]}"${G('mlp.'+x.id+'.st','NI')===o[0]?' selected':''}>${o[1]}</option>`).join('')}</select>`:''}<span class="print-only">${esc(({NI:'لم يُنفذ',PI:'نُفذ جزئيًا',IM:'نُفذ',NA:'لم يعد ينطبق'})[G('mlp.'+x.id+'.st','NI')])}</span></td></tr>`).join('')}</tbody></table>`:'<p>لا توجد ملاحظات من السنة السابقة مسجلة.</p>')+(can('edit')?`<p class="noprint"><button class="btn g sm" type="button" data-act="mlprior">⤓ استيراد الملاحظات المفتوحة من ارتباط السنة السابقة</button></p>`:'')},
 AJE_TABLE:()=>{const a=recs(CUR.eng,'a');return a.length?adjTable(a,true).replace(/<td class="noprint">.*?<\/td>/g,''):'<p>لا توجد تسويات مسجلة.</p>'},
 AJE_EVAL:()=>{const a=recs(CUR.eng,'a');let un=0,ad=0;a.forEach(x=>{const v=Math.abs(num(x.amt));if(x.adj==='Adjusted')ad+=v;else un+=v});const om=num(G('eng.mat',0)),ct=num(G('eng.ct',0));
  if(!om)return `<p>إجمالي التحريفات المصححة ${fmtN(ad)} وغير المصححة ${fmtN(un)}. <mark class="miss">لم تُحدد الأهمية النسبية بعد (تبويب العينات والأهمية).</mark></p>`;const pc=Math.round(un*100/om);
  return `<p>إجمالي التحريفات المصححة: <b>${fmtN(ad)}</b> — إجمالي التحريفات غير المصححة: <b>${fmtN(un)}</b> (${pc}% من الأهمية النسبية الكلية ${fmtN(om)}؛ حد الضآلة ${fmtN(ct)}).</p><p>${un>om?'⚠ التحريفات غير المصححة تتجاوز الأهمية النسبية الكلية؛ يجب طلب تصحيحها، وإلا يُعدَّل الرأي (ISA 705).':un>om*0.5?'التحريفات غير المصححة أقل من الأهمية النسبية لكنها تقترب منها؛ ينبغي تقييم الاعتبارات النوعية وخطر التحريفات غير المكتشفة (ISA 450).':'التحريفات غير المصححة غير جوهرية منفردة ومجتمعة، مع مراعاة الاعتبارات النوعية (ISA 450).'}</p>`},
 ENG_STATUS:()=>{const pr=prog(PROCS.map(p=>p.id));const wps=W.filter(w=>['CL','FN'].includes(G('wp.'+w[0]+'.wf'))).length;return `<ul><li>الإجراءات المكتملة: ${pr.d} من ${pr.t} (${pr.p}%)، استثناءات: ${pr.ex}.</li><li>أوراق العمل المخلاة أو النهائية: ${wps} من ${W.length}.</li><li>الملاحظات المسجلة: ${recs(CUR.eng,'f').length}، التسويات: ${recs(CUR.eng,'a').length}.</li></ul>`},
 OPEN_ITEMS:()=>{const rn=recs(CUR.eng,'r').filter(r=>r.status!=='Cleared'),fo=recs(CUR.eng,'f').filter(f=>!['Cleared','Adjusted','Passed'].includes(f.status||'Open'));return `<ul><li>ملاحظات مراجعة مفتوحة: ${rn.length}${rn.length?' — '+rn.slice(0,10).map(r=>'RN-'+esc(r.no||'')).join('، '):''}</li><li>ملاحظات/استثناءات مفتوحة: ${fo.length}</li><li>نماذج غير نهائية: ${TPL.filter(t=>['DR','RV'].includes(G('doc.'+t.id+'.st','NS'))).map(t=>esc(t.ar)).join('، ')||'لا يوجد'}</li></ul>`},
 OPINION:()=>{const op=docOpt('audrep','op');return `<p>نوع الرأي المختار في تقرير مراقب الحسابات: <b>${esc((TPLM.audrep.opts[0][2].find(x=>x[0]===op)||[])[1]||op)}</b>. <a class="noprint" href="${L('form/audrep')}">فتح التقرير</a></p>`},
 CTRL_TABLE:()=>{const rows=C.map(c=>{const ids=PROCS.filter(p=>p.src==='cyc'&&p.sid===c.id&&p.t==='TOC').map(p=>p.id);const g=prog(ids);return [c.n,ids.length,g.d,g.ex]});rows.push(['الرقابة العامة لتقنية المعلومات (ITGC)',...(()=>{const ids=PROCS.filter(p=>p.src==='itc').map(p=>p.id);const g=prog(ids);return [ids.length,g.d,g.ex]})()]);
  return `<table class="dtab"><thead><tr><th>الدورة</th><th>اختبارات الرقابة</th><th>المكتمل</th><th>الاستثناءات</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${esc(r[0])}</td><td>${r[1]}</td><td>${r[2]}</td><td>${r[3]?`<b class="bad">${r[3]}</b>`:0}</td></tr>`).join('')}</tbody></table>`},
 TB_ANALYTICS:()=>typeof TBSTORE!=='undefined'&&TBSTORE.ready()?tbAnalyticsHTML(true):'<p><mark class="miss">لم يُرفع ميزان مراجعة لهذا الارتباط بعد (تبويب ميزان المراجعة).</mark></p>'};
function mlManagerHTML(id){return `<div class="card noprint" data-block="mlm|${esc(id)}">${mlManagerInner(id)}</div>`}
function mlManagerInner(id){const P=mlPoints();const seen=mlSeen();const ed=can('edit');const nNew=P.filter(p=>!seen.has(p.key)).length;
 return `<h2 style="margin-top:0">النقاط المولَّدة آليًا <span class="cnt">${P.filter(p=>p.inc).length} / ${P.length}</span>${nNew?` <span class="b M">${nNew} جديدة منذ آخر اعتماد</span>`:''}</h2>
 <p class="mut small">المصادر: الملاحظات المسجلة (غير المخلاة)، الإجراءات بحالة «استثناء» دون ملاحظة مرتبطة، إجابات «لا» في استبيانات الرقابة الداخلية، وفروق الميزان مع الجداول الرئيسية. التحرير هنا لا يغيّر السجل الأصلي، ويبقى بعد إعادة التوليد.</p>
 ${P.length?`<div class="tw"><table><thead><tr><th>تضمين</th><th>النقطة</th><th>الفئة</th><th>الأهمية</th><th>المصدر</th><th class="noprint">تحرير</th></tr></thead><tbody>${P.map(p=>`<tr${seen.has(p.key)?'':' class="isnew"'}><td><input type="checkbox" data-k="ml.${esc(p.key)}.inc" aria-label="تضمين النقطة في الخطاب"${p.inc?' checked':''}${ed?'':' disabled'}></td><td class="tx">${seen.has(p.key)?'':'<span class="b M">جديد</span> '}${esc(p.title||'')}</td>
  <td><select class="sel" data-k="ml.${esc(p.key)}.cat" data-dv="${esc(p.cat)}" aria-label="الفئة"${ed?'':' disabled'}>${Object.keys(MLCAT).map(c=>`<option value="${c}"${p.cat===c?' selected':''}>${esc(MLCAT[c][0].split(' (')[0])}</option>`).join('')}</select></td>
  <td><select class="sel" data-k="ml.${esc(p.key)}.sev" data-dv="${esc(p.sev)}" aria-label="الأهمية"${ed?'':' disabled'}>${['H','M','L'].map(s=>`<option value="${s}"${p.sev===s?' selected':''}>${sevL(s)}</option>`).join('')}</select></td>
  <td>${nodeLink(p.src)}</td><td class="noprint"><details class="nt"><summary>✎ الحقول</summary><div class="fgrid">${[['title','العنوان']].concat(MLF).map(f=>`<label class="full">${esc(f[1])}</label>${edcML(p,f[0])}`).join('')}</div></details></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty"><p>لا توجد مصادر بعد.</p><p class="mut small">سجّل الملاحظات من «الملاحظات والتسويات»، أو ضع حالة «استثناء» على أي إجراء، وستظهر هنا آليًا.</p></div>'}
 ${ed&&P.length?`<div class="row"><button class="btn g sm" type="button" data-act="mlseen">✓ اعتماد التوليد الحالي (إزالة علامة «جديد»)</button></div>`:''}`}
function edcML(p,f){const k='ml.'+p.key+'.'+f;const cur=G(k,null);return `<div class="ed" contenteditable="${RO()?'false':CE}" role="textbox" aria-multiline="true" aria-label="${esc(f)}" data-k="${esc(k)}" data-dv="${esc(p[f]||'')}">${esc(cur!=null?cur:(p[f]||''))}</div>`}

/* ---------- ISA 705 opinion helper ---------- */
const OPMX={M:{0:'U',1:'Q',2:'A'},S:{0:'U',1:'Q',2:'D'}};
function opinionHelperHTML(){const a=recs(CUR.eng,'a');let un=0;a.forEach(x=>{if(x.adj!=='Adjusted')un+=Math.abs(num(x.amt))});const om=num(G('eng.mat',0));
 return `<div class="card noprint"><h3 style="margin-top:0">مساعد تحديد نوع الرأي (ISA 705)</h3><div class="fgrid"><label>طبيعة الأمر<select class="sel" id="ohN"><option value="M">القوائم المالية محرفة جوهريًا</option><option value="S">عدم القدرة على الحصول على أدلة كافية ومناسبة</option></select></label><label>تقدير المراجع لانتشار الأثر<select class="sel" id="ohE"><option value="0">لا يوجد أمر جوهري</option><option value="1">جوهري لكنه غير منتشر</option><option value="2">جوهري ومنتشر</option></select></label><div><button class="btn sm" type="button" data-act="ohapply">تطبيق على التقرير</button></div></div>
 <p class="small">مصفوفة ISA 705: تحريف جوهري غير منتشر ← متحفظ · تحريف جوهري منتشر ← معاكس · عدم كفاية الأدلة (جوهري غير منتشر) ← متحفظ · عدم كفاية الأدلة (جوهري منتشر محتمل) ← امتناع.</p>
 ${om?`<p class="small ${un>om?'note bad':'mut'}">التحريفات غير المصححة حاليًا ${fmtN(un)} مقابل أهمية نسبية ${fmtN(om)}${un>om?' — تتجاوز الأهمية النسبية؛ راجع نوع الرأي.':'.'}</p>`:''}
 <p class="mut small">ملاحظة: عند الامتناع عن إبداء الرأي تُحذف آليًا أقسام «أمور المراجعة الرئيسية» و«المعلومات الأخرى» ما لم يتطلبها نظام (ISA 705)، وعند المنشآت المدرجة يُدرج قسم أمور المراجعة الرئيسية (ISA 701).</p></div>`}

/* ---------- views ---------- */
V.forms=function(){const ed=can('edit');const st=t=>{const v=G('doc.'+t.id+'.st','NS');return `<span class="b ${v==='FN'?'ok':v==='NS'?'':'M'}">${esc((DOCST.find(x=>x[0]===v)||DOCST[0])[1])}</span>`};
 return `<h1>📝 النماذج والتقارير والخطابات</h1><p class="sub">${TPL.length} نموذجًا جاهزًا مرتبطًا بالمعايير وبأوراق العمل. تُملأ الحقول المشتركة آليًا من بيانات الارتباط، ويُحفظ كل نموذج مع الارتباط (documents/) ويُطبع على A4.</p>
 <details class="card"${ENGF.some(f=>!G('eng.'+f[0]))?' open':''}><summary><b>البيانات المشتركة للنماذج</b> <span class="mut small">(تُستخدم في كل الخطابات والتقارير)</span></summary><div class="fgrid">${ENGF.map(f=>f[2]==='jur'?`<label>${esc(f[1])}<select class="sel" data-k="eng.jur" data-dv="INT"${ed?'':' disabled'}>${[['INT','دولي (ISA / IESBA)'],['EG','مصر'],['SA','السعودية']].map(o=>`<option value="${o[0]}"${G('eng.jur','INT')===o[0]?' selected':''}>${o[1]}</option>`).join('')}</select></label>`:`<label>${esc(f[1])}<input class="in" data-k="eng.${f[0]}" ${f[2]==='date'?'type="date"':''} value="${esc(G('eng.'+f[0],''))}" placeholder="${esc(f[3]||'')}"${ed?'':' readonly'}></label>`).join('')}</div>
 <p class="mut small">اسم الشركة والسنة والفترة والإطار من بيانات الارتباط، واسم المكتب من الإعدادات، والأهمية النسبية من تبويب العينات والأهمية.</p></details>
 ${TPLCAT.map(c=>{const l=TPL.filter(t=>t.cat===c[0]);return l.length?`<h2>${esc(c[1])} <span class="cnt">${l.length}</span></h2><div class="tw"><table><thead><tr><th>النموذج</th><th>المعيار</th><th>أوراق العمل</th><th>الحالة</th><th>توليد آلي</th></tr></thead><tbody>${l.map(t=>`<tr><td><a href="${L('form/'+t.id)}"><b>${esc(t.ar)}</b></a><br><span class="mut small" dir="ltr">${esc(t.en)}</span>${t.review?' <span class="b M">بحاجة لمراجعة مهني</span>':''}</td><td>${stdTokens(t.isa).map(stdChip).join(' ')}</td><td>${wpL(t.wp)}</td><td>${st(t)}</td><td>${t.auto?'<span class="b ok">نعم</span>':''}</td></tr>`).join('')}</tbody></table></div>`:''}).join('')}
 <h2>فهرس النماذج حسب المعيار</h2>${isaTplIndex()}`};
function isaTplIndex(){const m={};TPL.forEach(t=>stdTokens(t.isa).forEach(x=>{(m[x]=m[x]||[]).push(t)}));const keys=Object.keys(m).sort((a,b)=>{const na=parseInt(a.replace(/\D/g,''))||9999,nb=parseInt(b.replace(/\D/g,''))||9999;return na-nb||a.localeCompare(b)});
 return `<div class="tw"><table><thead><tr><th>المعيار</th><th>النماذج</th></tr></thead><tbody>${keys.map(k=>`<tr><td><b dir="ltr">${ISASET.has(k)?`<a href="${L('isa/'+k)}">ISA ${esc(k)}</a>`:esc(k)}</b></td><td>${m[k].map(t=>`<a href="${L('form/'+t.id)}">${esc(t.ar)}</a>`).join(' · ')}</td></tr>`).join('')}</tbody></table></div>`}
V.form=function(id){const tp=TPLM[id];if(!tp)return `<div class="note bad">النموذج غير موجود.</div>`;CUR.lock=apFinal({t:'doc',id});const ed=can('edit')&&!CUR.lock;const k='doc.'+id;
 return `<h1>📝 ${esc(tp.ar)} <span class="mut small" dir="ltr">${esc(tp.en)}</span></h1>
 <p class="sub">${stdTokens(tp.isa).map(stdChip).join(' ')} ${tp.wp?'· أوراق العمل: '+wpL(tp.wp):''}</p><p>${esc(tp.desc)}</p>${tp.review?'<p class="note warn">⚠ بحاجة لمراجعة مهني قبل الاستخدام الرسمي.</p>':''}
 <div class="row noprint"><label>الحالة<select class="sel" data-k="${k}.st" data-dv="NS" aria-label="حالة النموذج"${ed?'':' disabled'}>${DOCST.map(s=>`<option value="${s[0]}"${G(k+'.st','NS')===s[0]?' selected':''}>${s[1]}</option>`).join('')}</select></label>
 <button class="btn g" type="button" data-act="print">🖨 طباعة / PDF</button><button class="btn g" type="button" data-act="docexp" data-id="${esc(id)}" data-fmt="docx">⤓ Word (.docx)</button>${ed?`<button class="btn g" type="button" data-act="docreset" data-id="${esc(id)}">↺ إلغاء كل التعديلات اليدوية</button>`:''}<a class="btn g" href="${L('forms')}">كل النماذج</a></div>
 <div data-block="ap|doc:${esc(id)}">${apHTML({t:'doc',id})}</div>
 ${tp.id==='audrep'&&ed?opinionHelperHTML():''}
 <div class="grid g2 noprint" data-live="docprev">${(tp.opts||[]).length?`<div class="card"><h3 style="margin-top:0">الخيارات</h3><div class="fgrid">${tp.opts.map(o=>`<label>${esc(o[1])}<select class="sel" data-k="${k}.o.${o[0]}" data-dv="${esc(o[3])}"${ed?'':' disabled'}>${o[2].map(v=>`<option value="${esc(v[0])}"${docOpt(id,o[0])===v[0]?' selected':''}>${esc(v[1])}</option>`).join('')}</select></label>`).join('')}</div></div>`:''}
 ${(tp.vars||[]).length?`<div class="card"><h3 style="margin-top:0">حقول هذا النموذج</h3><div class="fgrid">${tp.vars.map(v=>v[0].endsWith('text')||v[0]==='qmatter'?`<label class="full">${esc(v[1])}<textarea class="ta" data-k="${k}.v.${v[0]}"${ed?'':' readonly'}>${esc(G(k+'.v.'+v[0],v[2]||''))}</textarea></label>`:`<label>${esc(v[1])}<input class="in" data-k="${k}.v.${v[0]}" value="${esc(G(k+'.v.'+v[0],v[2]||''))}"${ed?'':' readonly'}></label>`).join('')}</div></div>`:''}
 <div class="card"><h3 style="margin-top:0">الحقول المشتركة</h3><p class="small">${['company','year','period','fw','partner','addr','rdate'].map(x=>`${esc(VARLABEL[x]||x)}: <b>${esc(docVars(id)[x]||'—')}</b>`).join(' · ')}</p><a class="small" href="${L('forms')}">تعديل البيانات المشتركة</a></div></div>
 ${tp.auto==='ml'||tp.auto==='mlsig'||tp.auto==='mlctrl'?mlManagerHTML(id):''}
 <h2 class="noprint">المعاينة</h2><div data-block="docprev|${esc(id)}">${docHTML(id,true)}</div>`};
BLOCKS.docprev=id=>docHTML(id||CUR.arg,true);
BLOCKS.mlm=id=>mlManagerInner(id);
/* edit one section in place (textarea bound to the override key) */
function docSecEdit(id,sid,btn){const sec=btn.closest('.docsec');const body=sec.querySelector('.secbody');const k='doc.'+id+'.s.'+sid;
 if(btn.getAttribute('aria-expanded')==='true'){btn.setAttribute('aria-expanded','false');btn.textContent='✎ تحرير القسم';refreshBlock('docprev|'+id);return}
 const m=docModel(id).secs.find(s=>s.sid===sid);btn.setAttribute('aria-expanded','true');btn.textContent='✓ إنهاء التحرير';
 body.innerHTML=`<p class="mut small">اكتب النص بحرية؛ افصل الفقرات بسطر فارغ وابدأ البند بـ «- ». يمكن استخدام الحقول مثل {{company}}. يُحفظ تلقائيًا.</p><textarea class="ta" data-k="${esc(k)}" aria-label="نص القسم">${esc(m?m.text:'')}</textarea>`;const ta=body.querySelector('textarea');autogrow(ta);ta.focus()}
async function mlImportPrior(){const y=parseInt(G('eng.year',''),10);if(!y){toast('سنة الارتباط غير رقمية.','w');return}await CO.load();const c=CO.byId(CUR.company.id);const path=c._dir+'/'+sanitizeName(String(y-1),20);
 if(!(await STORE.stat(path+'/engagement.json'))){toast('لا يوجد ارتباط للسنة '+(y-1)+' لهذه الشركة.','w');return}const prev=await storeFor(path);const P=mlPoints(prev).filter(p=>p.inc);
 let n=0;P.forEach(p=>{if(CUR.eng.get('mlp.'+p.key,null))return;CUR.eng.set('mlp.'+p.key,{cond:p.title+' — '+p.cond,rec:p.rec,from:y-1},{label:'استيراد ملاحظة سابقة'});n++});toast(n?`تم استيراد ${n} ملاحظة من ${y-1}.`:'لا توجد ملاحظات جديدة للاستيراد.','s');refreshBlock('docprev|'+CUR.arg)}
